INSERT INTO "world"."locales_faction" ("entry", "name_loc1", "name_loc2", "name_loc3", "name_loc4", "name_loc5", "name_loc6", "description_loc1", "description_loc2", "description_loc3", "description_loc4", "description_loc5", "description_loc6") VALUES
(229, '통곡의 동굴', 'Cavernes des lamentations', 'Die Höhlen des Wehklagens', '哀嚎洞穴', '哀嚎洞穴', 'Cuevas de los Lamentos', '', '', '', '', '', ''),
(249, '실리시드', 'Silithides', 'Sillithid', '异种蝎', '異種蠍', 'Silítidos', '', '', '', '', '', ''),
(269, '실버문 생존자', 'Survivants de Lune-d''argent', 'Überlebende aus Silbermond', '银月幸存者', '銀月倖存者', 'Lunargenta Despogiz', '', '', '', '', '', ''),
(270, '잔달라 부족', 'Tribu Zandalar', 'Stamm der Zandalar', '赞达拉部族', '贊達拉部族', 'Tribu Zandalar', '잔달라 부족은 요잠바 섬으로 와서 줄구룹의 부활한 혈신과 아탈라이 사제에 맞서 싸우기 위해 모험가들의 도움을 구하고 있습니다.', 'Ces trolls sont venus sur l’île de Yojamba pour tenter de trouver de l’aide contre le Dieu sanglant ressuscité et ses prêtres atal’ai, à Zul''Gurub.', 'Diese Trolle sind zur Insel Yojamba gereist, um Hilfe im Kampf gegen den wiederauferstandenen Blutgott und seine Priester der Atal''ai in Zul''Gurub zu erbitten.', '这群居住在尤亚姆巴岛的巨魔正在努力招募全世界的勇士，希望他们能够帮助自己对抗祖尔格拉布中的邪神哈卡以及他的阿塔莱祭司们。', '食人妖已在尤亞姆巴島上努力招募幫手，對抗復活的血神，以及祖爾格拉布的阿塔萊祭司。', 'Estos trols han acudido a la isla de Yojamba en un esfuerzo por conseguir aliados contra el resurrecto Dios Sangriento y sus sacerdotes Atal''ai en Zul''Gurub.'),
(289, ' 대장기술 - 무기 제작', ' Forge - Fabricant d''armes', ' Schmiedekunst - Waffenschmiedekunst', '黑水海盗', ' 鍛造 - 武器鑄造', ' Herrería: armas', '', '', '', '', '', ''),
(309, '전갈', 'Scorpide', 'Skorpid', '蝎子', '蠍子', 'Escórpido', '', '', '', '', '', ''),
(310, '야수 - 박쥐', 'Bête - Chauve-souris', 'Wildtier - Fledermaus', '蝙蝠', '蝙蝠', 'Bestia: murciélago', '', '', '', '', '', ''),
(311, '티탄', 'Titan', 'Titanisch', '泰坦', '泰坦', 'Titán', '', '', '', '', '', ''),
(329, '감독관 피즐', 'Sous-chef Fizzule', 'Zuchtmeister Fizzule', '工头费苏勒', '工頭費蘇勒', 'Capataz Burbujita', '', '', '', '', '', ''),
(349, '라벤홀트 암살단', 'Ravenholdt', 'Ravenholdt', '拉文霍德', '拉文霍德', 'Ravenholdt', '도적과 암살자 길드인 라벤홀트 암살단의 일원이 되려면 비상한 솜씨를 지녀야 합니다. 비밀결사대와는 적대 관계입니다.', 'Cette guilde de voleurs et d’assassins, ennemie jurée du Syndicat, n’accepte que les individus les plus talentueux.', 'Diese Gilde von Dieben und Meuchelmördern heißt nur jene willkommen, die über außergewöhnliches Können verfügen. Erzrivalen des Syndikats.', '这个由盗贼与刺客组成的行会只欢迎那些有着出色实力的人进入他们的领地。他们也是辛迪加的仇敌。', '這個小偷與刺客公會，只歡迎身懷非凡卓越本事的人加入。辛迪加的世仇。', 'La hermandad de ladrones y asesinos solo da la bienvenida a los más aguerridos. Son enemigos acérrimos del Sindicato.'),
(369, '가젯잔', 'Gadgetzan', 'Gadgetzan', '加基森', '加基森', 'Gadgetzan', '스팀휘들 무역회사의 수도인 이곳은 고블린 최고의 기술자들과 연금술사, 상인들의 고향입니다.', 'Capitale du cartel Gentepression, c’est la demeure des meilleurs ingénieurs, alchimistes et marchands gobelins.', 'Hauptstadt des Steamwheedle-Kartells und die Heimat der besten Ingenieure, Alchemisten und Händler, die die Goblins zu bieten haben.', '热砂集团的首府，诸多优秀地精技师、炼金师和商人的家乡。', '熱沙公司首都，同為哥布林最精良工程師、化學家和商人之都。', 'Capital del Cártel Bonvapor y hogar de los mejores ingenieros, alquimistas y mercaderes goblin.'),
(389, '놈리건 버그', 'Insecte de Gnomeregan', 'Gnomeregan-Bug', 'Gnomeregan Bug', '諾姆瑞根蟲', 'Bicho de Gnomeregan', '', '', '', '', '', ''),
(409, '하피', 'Harpie', 'Harpyie', '鹰身人', '鷹身人', 'Arpía', '', '', '', '', '', ''),
(429, '불타는 칼날단', 'Lame ardente', 'Brennende Klinge', '火刃氏族', '火刃氏族', 'Filo Ardiente', '', '', '', '', '', ''),
(449, '그늘거미 밀렵꾼', 'Braconnier Ombresoie', 'Schattenseidewilderer', '暗影蛛丝偷猎者', '暗影蛛絲偷獵者', 'Furtivo Sedaumbría', '', '', '', '', '', ''),
(450, '용암거미', 'Araignée des Vents brûlants', 'Sengende Spinne', 'Searing Spider', '灼熱蜘蛛', 'Araña abrasadora', '', '', '', '', '', ''),
(469, '얼라이언스 연합', 'Alliance', 'Allianz', '联盟', '聯盟', 'Alianza', '', '', '', '', '', ''),
(470, '톱니항', 'Ratchet', 'Ratchet', '棘齿城', '棘齒城', 'Trinquete', '스팀휘들 무역회사의 지부인 이곳은 불모의 땅에서 여러 상품을 거래하고자 하는 이들에겐 천국과 같은 곳입니다.', 'Cette ville gobeline appartient au cartel Gentepression. Elle offre un abri neutre à tous ceux qui veulent échanger des biens et des services dans les Tarides.', 'Diese neutrale Goblinstadt, ein Teil des Steamwheedle-Kartells, ist ein sicherer Hafen für all jene, die im Brachland mit Waren und Dienstleistungen handeln wollen.', '热砂集团的成员，这座城市给许多希望在贫瘠之地做生意的人提供了一个开放和中立的天堂。', '隸屬於熱砂公司的一部份。這座哥布林城是中立的庇護所，專門給貧瘠之地從事貨物交易與服務的商人。', 'Parte del Cártel Bonvapor, esta ciudad goblin constituye un santuario neutral para los que desean realizar intercambios comerciales y de servicios en los Baldíos.'),
(471, '와일드해머 드워프', 'Clan Wildhammer', 'Wildhammerklan', '蛮锤部族', '蠻錘部族', 'Clan Martillo Salvaje', '맹금의 봉우리에 살고 있는 와일드해머 드워프들은 비록 얼라이언스의 일원은 아니지만 얼라이언스와 협력 관계를 유지하고 있으며 호드와는 적대 관계입니다.', 'Même s’ils n’appartiennent pas à l’Alliance, les nains du Nid-de-l’Aigle lui ont ouvert leurs portes et considèrent les peuples de la Horde comme des ennemis.', 'Obgleich sie der Allianz nicht angehören, haben die Zwerge von Aerie Peak ihr die Tore geöffnet und sehen die Horde als den Feind an.', '尽管并非是联盟的一份子，但鹰巢山的矮人还是将联盟视为他们的朋友，并与部落保持着交战关系。', '雖不屬於聯盟的一份子，鷹巢山上的矮人仍歡迎他們，並視部落為仇敵。', 'A pesar de no formar parte de la Alianza, los enanos de Pico Nidal les han abierto sus puertas y consideran a la Horda como el enemigo.'),
(489, '고블린 - 검은무쇠 주점 손님', 'Gobelin, client du bar sombrefer', 'Goblin, Dunkeleisen (Bargast)', 'Goblin, Dark Iron Bar Patron', '黑鐵酒吧哥布林老闆', 'Goblin, Dueño de un bar de Hierro Negro', '', '', '', '', '', ''),
(509, '아라소르 연맹', 'La Ligue d''Arathor', 'Der Bund von Arathor', '阿拉索联军', '阿拉索聯軍', 'Liga de Arathor', '스톰윈드의 후원을 받고 있는 아라소르 연맹은 아라시 분지의 잃어버린 땅을 되찾기 위해 투쟁하고 있습니다.', 'La Ligue d’Arathor tente de récupérer les terres perdues du bassin d’Arathi pour le compte de ses bienfaiteurs de Stormwind.', 'Der Bund von Arathor will verlorene Ländereien des Arathibeckens wieder für ihre Gönner in Stormwind zurückgewinnen.', '阿拉索联军正试图为暴风城夺回阿拉希盆地。', '阿拉索聯軍想辦法替暴風城的保護人，收回阿拉希盆地所丟失的土地。', 'La Liga de Arathor persigue reclamar las tierras perdidas de Arathi para el beneficio de sus benefactores en Ventormenta.'),
(510, '포세이큰 파멸단', 'Les Profanateurs', 'Die Entweihten', '污染者', '污染者', 'Los Rapiñadores', '포세이큰 파멸단은 호드를 위해 아라소르 분지에 있는 귀중한 자원을 차지하기 위한 투쟁을 벌이고 있습니다.', 'Les Profanateurs cherchent à s’emparer des ressources inestimables du bassin d’Arathi au profit de la Horde.', 'Die Entweihten wollen die wertvollen Ressourcen des Arathibeckens für die Horde gewinnen.', '污染者试图为部落夺取阿拉希盆地的重要资源。', '污染者想幫部落尋求阿拉希盆地珍稀的資源。', 'Los Rapiñadores buscan hacerse con el control de los valiosos recursos de Arathi para el beneficio de la Horda.'),
(511, '거인', 'Géant', 'Riese', '巨人', '巨人', 'Gigante', '', '', '', '', '', ''),
(529, '은빛 여명회', 'Aube d''argent', 'Argentumdämmerung', '银色黎明', '銀色黎明', 'Alba Argenta', '스컬지의 위협에서 아제로스를 지켜내고자 결성된 단체입니다. 은빛 여명회의 주요 거점은 동부 및 서부 역병지대에 위치하고 있습니다.', 'Cette organisation s’est vouée à protéger Azeroth contre la menace du Fléau. On trouve ses forteresses dans les Maleterres de l’est et de l’ouest.', 'Eine Organisation, die es sich zum Ziel gesetzt hat, Azeroth vor der Bedrohung durch die Geißel zu beschützen. Stützpunkte der Argentumdämmerung befinden sich in den östlichen und westlichen Pestländern.', '一个致力于从亡灵天灾军团的威胁下拯救艾泽拉斯世界的组织。银色黎明的据点遍布东西瘟疫之地。', '專門保護艾澤拉斯免受天譴軍團威脅的組織。銀色黎明的大本營就在東瘟疫之地和西瘟疫之地。', 'Una organización centrada en proteger Azeroth de la amenaza de la Plaga. Las fortalezas del Alba Argenta se encuentran en las Tierras de la Peste del Este y del Oeste.'),
(530, '검은창 트롤', 'Trolls Darkspear', 'Darkspear', '暗矛巨魔', '暗矛食人妖', 'Trols de Lanza Negra', '트롤 사회에서 추방당한 검은창 부족은 스랄과 손을 잡고 호드 진영과 힘을 합치게 됩니다. 이제 그들은 동맹인 오크들과 함께 듀로타에 터전을 마련하여 생활하고 있습니다.', 'Cette tribu de trolls exilés a joint ses forces à celles de Thrall et de la Horde. Ils partagent désormais Durotar avec leurs alliés orcs.', 'Dieser Stamm von verbannten Trollen hat sich Thrall und der Horde angeschlossen. Ihr Zuhause ist nun Durotar, welches sie sich mit den Orcs teilen.', '一群被放逐的巨魔，加入了萨尔领导下的部落。他们现在将杜隆塔尔当作自己的新家，并与兽人盟友们一起生活在那里。', '流亡的食人妖部族加入了索爾和部落的行列。他們現在以杜洛塔為家，並與獸人同盟為伍。', 'Esta tribu de trols exiliados ha unido fuerzas con Thrall y la Horda. Ahora conviven con los orcos en las tierras de Durotar.'),
(531, '용군단 - 청동용군단', 'Vol de bronze', 'Drachenschwarm, Bronze', '青铜龙军团', '青銅龍軍團', 'Vuelo, Bronce', '', '', '', '', '', ''),
(532, '용군단 - 푸른용군단', 'Vol bleu', 'Drachenschwarm, Blau', '蓝龙军团', '藍龍軍團', 'Vuelo, Azul', '', '', '', '', '', ''),
(549, ' 가죽세공 - 부족전통', ' Travail du cuir - Tribal', ' Lederverarbeitung - Stamm', ' Leatherworking - Tribal', ' 製皮 - 部落', ' Peletería: tribal', '', '', '', '', '', ''),
(550, ' 기계공학 - 고블린', ' Ingénieur - Gobelin', ' Ingenieurskunst - Goblin', ' Engineering - Goblin', ' 工程學 - 哥布林', ' Ingeniería: goblin', '', '', '', '', '', ''),
(551, ' 기계공학 - 노움', ' Ingénieur - Gnome', ' Ingenieurskunst - Gnom', ' Engineering - Gnome', ' 工程學 - 地精', ' Ingeniería: gnoma', '', '', '', '', '', ''),
(569, ' 대장기술 - 망치 제작', ' Forge - Fabricant de marteaux', ' Schmiedekunst - Hammerschmiedekunst', ' Blacksmithing - Hammersmithing', ' 鍛造 - 槌類鍛造', ' Herrería: martillos', '', '', '', '', '', ''),
(570, ' 대장기술 - 도끼 제작', ' Forge - Fabricant de haches', ' Schmiedekunst - Axtschmiedekunst', ' Blacksmithing - Axesmithing', ' 鍛造 - 斧類鍛造', ' Herrería: hachas', '', '', '', '', '', ''),
(571, ' 대장기술 - 검 제작', ' Forge - Fabricant d''épées', ' Schmiedekunst - Schwertschmiedekunst', ' Blacksmithing - Swordsmithing', ' 鍛造 - 劍類鍛造', ' Herrería: espadas', '', '', '', '', '', ''),
(572, '트롤 - 썩은가지부족', 'Troll, Vilebranch', 'Troll, Vilebranch', '邪枝巨魔', '邪枝食人妖', 'Trol, Vilrama', '', '', '', '', '', ''),
(573, '남쪽바다 해적단', 'Flibustiers des Mers du sud', 'Südmeerfreibeuter', '南海海盗', '南海海盜', 'Filibusteros del Mar del Sur', '', '', '', '', '', ''),
(574, '카엘 다로우', 'Caer Darrow', 'Caer Darrow', '凯尔达隆', '凱爾達隆', 'Castel Darrow', '', '', '', '', '', ''),
(575, '오염되지 않은 펄볼그', 'Furbolg, non corrompu', 'Furbolg, nicht verderbt', '未堕落的熊怪', '未墮落的熊怪', 'Fúrbolg, incorrupto', '', '', '', '', '', ''),
(576, '나무구렁 요새', 'Les Grumegueules', 'Holzschlundfeste', '木喉要塞', '木喉要塞', 'Bastión de los Fauces de Madera', '타락하지 않은 마지막 펄볼그 부족인 나무구렁부족은 동족의 고통을 끝내고 자신들의 주체성을 지킬 방법을 모색하고 있습니다.', 'Les Grumegueules sont la dernière tribu furbolg à échapper à la corruption. Ils cherchent à préserver leur spiritualité et à mettre un terme aux souffrances de leur peuple.', 'Als der letzte unverderbte Stamm der Furbolgs, wollen die Furbolgs der Holzschlundfeste ihren spirituellen Lebensweg bewahren und das Leiden ihrer Artgenossen beenden.', '作为最后一支尚未堕落的熊怪部族，木喉部族正致力于保留他们那种独特的精神修行之道，并试图终结其他熊怪部族的痛苦。', '身為最後一個尚未墮落的熊怪部族，木喉還在尋求保護心智的方法以終結同胞的受難。', 'Como la última tribu fúrbolg sin corromper, los Fauces de Madera persiguen preservar sus tradiciones espirituales y acabar con el sufrimiento de sus congéneres.'),
(577, '눈망루 마을', 'Long-guet', 'Everlook', '永望镇', '永望鎮', 'Vista Eterna', '스팀휘들 무역회사의 고블린들이 무역 거점으로 운영 중인 이곳은 여명의 설원을 가로지르는 주 무역로가 교차되는 지점에 위치하고 있습니다.', 'Administré par les gobelins du cartel Gentepression, ce comptoir se trouve au croisement des routes commerciales du Berceau-de-l’hiver.', 'Dies ist ein von den Goblins des Steamwheedle-Kartells geführter Handelsposten, der sich im Zentrum der Haupthandelswege von Winterspring befindet.', '热砂集团经营之下的一座贸易城市，坐落于冬泉谷的两条主要干道的交叉处。', '熱砂公司的哥布林經營這座貿易商埠區，就位在冬泉谷主要貿易道路的十字路口上。', 'Este enclave comercial, regentado por los goblins del Cártel Bonvapor, se sitúa en el cruce de las principales rutas comerciales de Cuna del Invierno.'),
(589, '눈호랑이 조련사', 'Éleveurs de sabres-d''hiver', 'Wintersäblerausbilder', '冬刃豹训练师', '冬刃豹訓練師', 'Entrenadores de Sableinvernales', '이들은 은둔 중인 나이트 엘프들이며 여명의 설원에서 눈호랑이를 기르고 훈련시킵니다.', 'Ce petit groupe d’elfes de la nuit vit en reclus. Ses membres élèvent et dressent des sabres-d’hiver au Berceau-de-l’hiver.', 'Eine kleine Gruppe zurückgezogener Nachtelfen zieht in der Gegend von Winterspring Wintersäbler auf und bildet sie aus.', '这是一些专门在冬泉谷地区驯养冬泉霜刃豹的暗夜精灵。', '這個孤寂的夜精靈小團隊提升並訓練了冬泉谷區域的冬刃豹。', 'Estos pequeños grupos de recluidos elfos de la noche cría y amaestra sableinvernales en el  área de Cuna del invierno.'),
(609, '세나리온 의회', 'Cercle cénarien', 'Zirkel des Cenarius', '塞纳里奥议会', '塞納里奧議會', 'Círculo Cenarion', '세나리온 의회의 드루이드들은 자연의 수호자이며 평온한 달의 숲이 그들의 고향입니다.', 'Gardiens de la nature, les druides du Cercle cénarien ont établi leur demeure dans la paisible vallée de Reflet-de-Lune.', 'Die Druiden des Zirkels des Cenarius sind Beschützer der Natur und leben im friedlichen Moonglade.', '塞纳里奥议会的德鲁伊是自然的守卫者，他们定居于宁静的月光林地。', '塞納里奧的德魯伊是大自然的守護神，將寧靜的月光林地當成自己的家。', 'Los druidas del Círculo Cenarion son guardianes de la Naturaleza y conviven en el calmo Claro de la Luna.'),
(629, '트롤 - 뾰족창부족', 'Trolls Shatterspear', 'Shatterspear', '断矛巨魔', '斷矛食人妖', 'Trols Rompelanzas', '', '', '', '', '', ''),
